def link(slug):
    return 'index.html' if slug == 'index' else slug+'.html'

def frame(slug, title, body, home=False):
    pre = '' if home else '../'
    nav = '<a href="portfolio/index.html">Portfolio <span aria-hidden="true">↗</span></a><a href="portfolio/social.html">Social Media</a>' if home else ''.join(f'<a href="{link(s)}"'+(' aria-current="page"' if s==slug else '')+f'>{label}</a>' for s,label in pages)
    return f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Christopher Horne, UNC Charlotte student meteorologist. Coursework, projects, experience, and a focus on weather intelligence and public communication."><meta name="theme-color" content="#18191A"><title>{title} | CH Weather</title><link rel="icon" href="{pre}assets/ch-weather-logo.png"><link rel="stylesheet" href="{pre}assets/styles.css"><script src="{pre}assets/site.js" defer></script></head>
<body><a class="skip" href="#main">Skip to content</a><div class="atmosphere" aria-hidden="true"></div>
{'' if home else '<div class="return-bar"><div class="wrap"><a href="../index.html">← Return to CH Weather</a><span>CHRISTOPHER HORNE / PORTFOLIO</span></div></div>'}
<header class="site-header wrap"><a class="identity" href="{ 'index.html' if home else 'index.html'}"><img src="{pre}assets/ch-weather-logo.png" alt="CH Weather" width="70" height="70"><span>{'CH WEATHER' if home else 'CHRISTOPHER HORNE'}<small>{'CAROLINA WEATHER, EXPLAINED.' if home else 'STUDENT METEOROLOGIST'}</small></span></a><button class="menu-button" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">+</span></button><nav id="navigation" aria-label="{'Main' if home else 'Portfolio'} navigation">{nav}</nav></header>
<main id="main" class="wrap">{body}</main>
<footer class="wrap"><div class="footer-top"><a class="identity" href="{pre}index.html"><img src="{pre}assets/ch-weather-logo.png" width="54" height="54" alt="CH Weather"><span>Understand what’s ahead.<small>Christopher Horne · Charlotte, North Carolina</small></span></a><div class="social-links">{social}</div></div><div class="footer-bottom"><span>© 2026 Christopher Horne · CH Weather</span><span>Student meteorologist · UNC Charlotte</span></div></footer></body></html>'''

def heading(n,k,t,d):
    return f'<section class="page-heading"><p class="eyebrow">{n} / {k}</p><h1>{t}</h1><p class="lede">{d}</p></section>'

def entry(meta,title,text):
    return f'<article class="entry"><p class="eyebrow">{meta}</p><div><h3>{title}</h3><p>{text}</p></div></article>'

